import{z as B,x as A,o as n,c as d,q as s,j as i,D as e,d as E,s as l,S as r,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"函数与可数","description":"","frontmatter":{"title":"函数与可数","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/functions-countable.md","filePath":"cs/functions-countable.md","lastUpdated":1791063341000}'),p={name:"cs/functions-countable.md"};function b(m,a,h,D,f,c){const o=A("Mermaid");return n(),d("div",null,[a[2]||(a[2]=s('<h1 id="函数与可数" tabindex="-1">函数与可数 <a class="header-anchor" href="#函数与可数" aria-label="Permalink to &quot;函数与可数&quot;">​</a></h1><div class="epigraph"><p>函数是右唯一的关系；两个集合一样大，当且仅当存在双射。可数，就是能和自然数一一对上。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications 整理</footer></div><p>上一课<a href="/cs/poset-lattice">偏序与格直觉</a>钉死了子集与有序对。本课不重讲自反对称传递，也不从「无穷哲学」另起。缺口是：关系太宽。计算要的是「每个输入恰好一个输出」，以及「这一堆对象能不能编号」。没有这两条，后课归纳没有指标集，渐近记号没有 \\(n\\to\\infty\\) 的对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>布尔函数已经是 \\(\\{0,1\\}^n\\to\\{0,1\\}\\)，但一般对应 \\(f:A\\to B\\) 要写成：对每个 \\(a\\in A\\) 恰有一个 \\(b\\) 使 \\((a,b)\\in f\\)。单射、满射、双射把「能否反推、能否盖住」说清。缺口的另一半：无限集不能靠数元素个数。Cantor 的标准：<strong>可数</strong>当且仅当与 \\(\\mathbb{N}\\) 存在单射（或等价地，有限或与 \\(\\mathbb{N}\\) 双射，说法按教材选一种并固定）。</p><p>\\(\\mathbb{N}\\)、\\(\\mathbb{Z}\\)、\\(\\mathbb{Q}\\) 可数；\\(\\{0,1\\}^{\\mathbb{N}}\\) 与 \\(\\mathbb{R}\\) 不可数——对角线。本课只要这个对照：比特串长度有限则有限；无限长比特序列已经不可数。后课算法输入默认有限串。</p><h3 id="可数不是「能列成程序打印出来」" tabindex="-1">可数不是「能列成程序打印出来」 <a class="header-anchor" href="#可数不是「能列成程序打印出来」" aria-label="Permalink to &quot;可数不是「能列成程序打印出来」&quot;">​</a></h3><p>可计算枚举是更严的一层，本课不要。可数只要求存在双射，不必给出算法。把「整数可数」说成「计算机能列完」，会与停机问题撞车，那是附录与计算理论，不插入本主干。</p><p><span class="marginnote">Rosen 把鸽笼原理写成有限单射的推论。可数无限的鸽笼要另说。本课的双射是计数的语言；渐近记号用的 \\(n\\) 是这个 \\(\\mathbb{N}\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检查右唯一与左完全得函数。复合、限制按集合定义。可数：给出枚举 \\(a_0,a_1,\\ldots\\) 允许重复则是满射 \\(\\mathbb{N}\\to A\\)，再收缩成双射。对角线：若 \\(f:\\mathbb{N}\\to\\{0,1\\}^{\\mathbb{N}}\\)，令 \\(d(i)=1-f(i)(i)\\)，则 \\(d\\) 不在值域。</p>',11)),(n(),i(r,null,{default:e(()=>[l(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REL%5B%22%E5%85%B3%E7%B3%BB%22%5D%20--%3E%20FUN%5B%22%E5%87%BD%E6%95%B0%EF%BC%9A%E5%8F%B3%E5%94%AF%E4%B8%80%22%5D%0A%20%20FUN%20--%3E%20BIJ%5B%22%E5%8F%8C%E5%B0%84%22%5D%0A%20%20BIJ%20--%3E%20CNT%5B%22%E5%8F%AF%E6%95%B0%20%2F%20%E4%B8%8D%E5%8F%AF%E6%95%B0%22%5D%0A%20%20CNT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%BD%92%E7%BA%B3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[E("有限字母表上的有限串 \\(\\Sigma^*\\) 可数：按长度再按字典序。这保证「所有程序」「所有有限图」可数，后课才能谈「某个算法是否存在」。不可数的对象（任意实数、任意无限执行轨迹）不能当输入写完。机器字是有限 \\(n\\)，所以"),t("a",{href:"/cs/positional-notation"},"进制"),E("的集合有限。")],-1)),a[5]||(a[5]=t("p",null,"鸽笼：有限集到更小有限集没有单射。后课哈希碰撞、鸽笼选重复，用的就是这一条，不另造原理。",-1)),a[6]||(a[6]=t("p",null,"对角线为什么必然造出漏网之鱼？沿着对角线逐位取反，新串与表中每一行都至少在一个位置不同。",-1)),(n(),i(r,null,{default:e(()=>[l(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%81%87%E8%AE%BE%EF%BC%9A%E6%9E%9A%E4%B8%BE%20f(0)%2C%20f(1)%2C%20%E2%80%A6%20%E7%9B%96%E4%BD%8F%E5%85%A8%E9%83%A8%E6%97%A0%E9%99%90%E6%AF%94%E7%89%B9%E4%B8%B2%22%5D%20--%3E%20B%5B%22%E6%9E%84%E9%80%A0%20d%EF%BC%9A%E7%AC%AC%20i%20%E4%BD%8D%20%3D%20f(i)%20%E7%9A%84%E7%AC%AC%20i%20%E4%BD%8D%E5%8F%96%E5%8F%8D%22%5D%0A%20%20B%20--%3E%20C%5B%22d%20%E4%B9%9F%E6%98%AF%E4%B8%80%E6%9D%A1%E6%97%A0%E9%99%90%E6%AF%94%E7%89%B9%E4%B8%B2%22%5D%0A%20%20C%20--%3E%20D%7B%22d%20%E8%83%BD%E7%AD%89%E4%BA%8E%E6%9F%90%E4%B8%AA%20f(k)%20%E5%90%97%EF%BC%9F%22%7D%0A%20%20D%20--%20%22%E6%AF%94%E8%BE%83%E7%AC%AC%20k%20%E4%BD%8D%22%20--%3E%20E%5B%22d%20%E7%9A%84%E7%AC%AC%20k%20%E4%BD%8D%E4%B8%8E%20f(k)%20%E7%9A%84%E7%AC%AC%20k%20%E4%BD%8D%E6%81%B0%E5%A5%BD%E7%9B%B8%E5%8F%8D%22%5D%0A%20%20E%20--%3E%20F%5B%22%E7%9F%9B%E7%9B%BE%EF%BC%9A%E6%9E%9A%E4%B8%BE%E5%BF%85%E7%84%B6%E6%BC%8F%E6%8E%89%20d%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">直觉类比：把枚举表想成一张课程表，每行是一门「无限长的选课单」。你沿对角线逐格改成相反选项，得到的新选课单与每一行都至少在对角位置不同——所以它绝不可能是表里的任何一行。</span></p><p><span class="marginnote">数字实例：长度 \\(n\\) 的比特串只有 \\(2^n\\) 个（\\(n=3\\) 时 8 个），再长也数得完；无限长比特串每条都像一位无限小数，硬要排成队就对角线法必漏一条。有限与无限的差别就在这里。</span></p><p><span class="marginnote">常见误区：初学者容易以为有理数处处稠密、比整数「多得多」，所以不可数。实际上 \\(\\mathbb{Q}\\) 可数——把分数按分子加分母的大小排队、重复的跳过即可。稠密与可数不矛盾，真正不可数的是 \\(\\mathbb{R}\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入基数 \\(\\aleph_1\\)、连续统假设。不把偏函数、可计算函数混进「函数」一词：后课算法可以在某些输入上不停，那是偏的，本课的函数是全函数。</p><p>后课默认：谈到编号、枚举、输入长度 \\(n\\)，集合是有限或可数；函数是右唯一的关系。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>函数是每个左端点恰好一条边的关系；双射定义「一样大」。</li><li>有限串可数；无限比特序列不可数。</li><li>鸽笼是有限单射的否定。归纳的指标是 \\(\\mathbb{N}\\)。</li><li>出处：Rosen, <em>Discrete Mathematics</em>。</li></ul>',8))])}const F=B(p,[["render",b]]);export{C as __pageData,F as default};
